import { ref, computed } from 'vue';

// Create the main Vue component
const ExpensiveComputationDemo = {
  setup() {
    // Initialize reactive state here
    const numberInput = ref(0);

    // Define expensive computation function here
    function expensiveCalculation(n) {
      // Simulate expensive computation
      let result = 0;
      for (let i = 0; i < 100000000; i++) {
        result += Math.sqrt(i) * Math.sin(i);
      }
      return n * 2;
    }

    // Create computed property here
    const computedResult = computed(() => expensiveCalculation(numberInput.value));

    // Add counter state and forceRender function here
    const renderCounter = ref(0);

    // Return template with input and result display
    return {
      numberInput,
      computedResult,
      renderCounter
    };
  },
  template: `
    <div>
      <input type="number" v-model="numberInput" />
      <p>Computed result: {{ computedResult }}</p>
      <button>Force Re-render</button>
      <p>Render count: {{ renderCounter }}</p>
    </div>
  `
};
